export type QuizDifficulty = 'easy' | 'medium' | 'hard'

export type QuizQuestion = {
  prompt: string
  options: string[]
  answer: number
  explanation: string
  difficulty?: QuizDifficulty
}

const q = (
  difficulty: QuizDifficulty,
  prompt: string,
  correct: string,
  distractorA: string,
  distractorB: string,
  explanation: string,
): QuizQuestion => ({
  difficulty,
  prompt,
  options: [correct, distractorA, distractorB],
  answer: 0,
  explanation,
})

